package `in`.shabinder.soundbound.matcher

/**
 * Names that MusicBrainz records for the same artist across scripts and spellings (王菲 / Faye Wong / 王靖雯,
 * 동방신기 / TVXQ! / 東方神起, 宇多田ヒカル / Hikaru Utada, BTS / 방탄소년단). [ArtistAliasData] holds one line per
 * artist, most listened first, generated by `ArtistAliasGenerator` (jvmTest) from the MusicBrainz artist dump
 * (CC0) ranked by ListenBrainz listen counts. Artists whose names the romanizer already links are left out.
 *
 * A key is the name in its own script, normalised, words sorted and joined, never romanised: 王飞 and 王菲 both read
 * "wang fei" but are different artists. Sorting makes the sort name "Wong, Faye" and "Faye Wong" one key.
 */
object ArtistAliases {
    private val groups: Map<String, Int> by lazy {
        val out = HashMap<String, Int>()
        ArtistAliasCodec.decode(ArtistAliasData.TABLE).split('\n').forEachIndexed { i, line ->
            for (k in line.split('|')) if (k.isNotEmpty()) out.getOrPut(k) { i }
        }
        out
    }
    // Copy-on-write so matcher threads read while a host registers. ponytail: two racing register calls can drop one
    // artist (it is looked up again next time); add a lock if hosts ever register in bulk from many threads.
    private var extra: Map<String, Int> = emptyMap()
    private var nextExtra = -1

    /** Lookup key of one credit, the same way the generator builds it. */
    fun key(name: String): String = RecordingMatch.normalizeText(name).split(' ').sorted().joinToString("")

    private fun groupOf(name: String): Int? = key(name).let { extra[it] ?: groups[it] }

    /** True when the table (or [register]) already knows [name]; hosts skip their runtime lookup then. */
    fun known(name: String): Boolean = groupOf(name) != null

    /** True when both credits are recorded names of one artist. */
    fun same(a: String, b: String): Boolean = groupOf(a)?.let { it == groupOf(b) } ?: false

    /**
     * Adds one artist's names at runtime (e.g. aliases a host fetched from MusicBrainz for an artist the table lacks).
     * Process-local; a key already in the table keeps its table artist.
     */
    fun register(names: Collection<String>) {
        val id = nextExtra--
        extra = extra + names.map(::key).filter { it.length >= 2 && it !in groups }.associateWith { id }
    }
}
